INSERT INTO public.valuations (
   date,
   asset_id,
   lot_id,
   methodology_id,
   clean_price,
   accrued_interest,
   indexer_id,
   indexer_percentage,
   spread_over_indexer,
   spread_over_cdi,
   spread_over_inflation,
   cash_flow,
   currency_id,
   last_valuation_flag,
   created_at
)
SELECT 
    d.raw_date::timestamptz,
    (SELECT id FROM public.entities WHERE name = d.asset_name LIMIT 1),
    d.lot_id,
    (SELECT id FROM public.valuation_methodologies WHERE name = d.methodology_name LIMIT 1) methodology_id,
    d.clean_price::decimal(20,8),
    d.accrued_interest::decimal(20,8),
    (SELECT id FROM public.indexers WHERE name = d.indexer_name LIMIT 1),
    d.indexer_percentage::decimal(12,8),
    d.spread_over_indexer::decimal(12,8),
    d.spread_over_cdi::decimal(12,8),
    null spread_over_inflation,
    d.cash_flow::decimal(20,8),
    (SELECT id FROM public.entities WHERE name = d.currency_name LIMIT 1) currency_id,
   CASE WHEN d.raw_date = '2025-04-16 00:00:00+00' THEN TRUE ELSE FALSE END,
   NOW()
FROM data_source d
ON CONFLICT (date, asset_id, lot_id, methodology_id) 
DO NOTHING
;

select * from valuations where asset_id in (29, 32)
order by asset_id, "date"
